INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8294,'zhTW','鎮壓銀翼部隊','梣谷森林將在強大的部落面前屈服，$r。無論暗夜精靈們說什麼做什麼，都無法阻止我們的推進。卡利姆多屬於部落，誰敢阻止我們拿取屬於我們的東西，誰就要死！$B$B讓你的心中充滿榮耀之光，讓那些膽敢阻止我們的敵人一個個倒下。摧毀銀翼要塞中的哨兵部隊，並拿到一枚戰歌榮譽獎章。把這樣一枚獎章給我拿來，你就可以獲得獎賞。','進入戰歌峽谷擊敗聯盟小隊，獲得一枚戰歌榮譽獎章，然後向莫爾杉營地的沙塔爾·碎顱覆命。','','去貧瘠之地找莫爾杉營地的沙塔爾·碎顱。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8295 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8295,'zhTW','鎮壓銀翼部隊','梣谷森林將在強大的部落面前屈服，$r。無論暗夜精靈們說什麼做什麼，都無法阻止我們的推進。卡利姆多屬於部落，誰敢阻止我們拿取屬於我們的東西，誰就要死！$B$B讓你的心中充滿榮耀之光，讓那些膽敢阻止我們的敵人一個個倒下。摧毀銀翼要塞中的哨兵部隊，並拿到一枚戰歌榮譽獎章。把這樣一枚獎章給我拿來，你就可以獲得獎賞。','進入戰歌峽谷擊敗聯盟小隊，獲得一枚戰歌榮譽獎章，然後向莫爾杉營地的沙塔爾·碎顱覆命。','','去貧瘠之地找莫爾杉營地的沙塔爾·碎顱。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8372,'zhTW','自然屏障','銀翼哨兵正在和戰歌前鋒部隊爭奪這片森林。當然，銀翼哨兵保護森林的原因並非只有熱愛大自然這條理由。$B$B梣谷的森林對我們來說是一層天然的戰略屏障，可以抵抗大規模的進攻。如果沒有這片森林的話，阿斯特蘭納很快就會完全暴露在貧瘠之地的攻擊部隊面前。你願意參加對抗戰歌前鋒的戰鬥嗎？為了聯盟！','將3枚戰歌峽谷榮譽獎章交給戰場外的聯盟準將。','','去找聯盟準將。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8399 AND `locale` = 'zhTW';
